import {coverageMarkup,bindCoverage} from './coverage-view.js?v=0.4.0';
import {REGIONS,JOBS,BG,JOB_COLORS,filterRecords,summarize,tally,csvCell,configure,CONFIG} from './core.js?v=0.4.0';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let records=[],catalog={},view='overview',filters={period:'cohorts',scope:'all',track:'all',origin:'all',school:'all',job:'all',destination:'all',topic:'all',method:'all',background:'all',q:''},comparison='ug_cn';
const cycleLabel=()=>catalog.current_cycle?catalog.current_cycle.slice(0,4)+'–'+catalog.current_cycle.slice(-2):'当季', archiveLabel=()=>`${catalog.history_years[0]}–${catalog.history_years.at(-1)}`;
const main=$('#main'),fmt=n=>n.toLocaleString('en-US'),percent=x=>x===null?'—':Math.round(x*100)+'%',option=(v,t,selected)=>`<option value="${esc(v)}" ${v===selected?'selected':''}>${esc(t)}</option>`;
const region=r=>REGIONS[r]||r||'未核验';
const safeUrl=u=>{try{const parsed=new URL(u);return ['http:','https:'].includes(parsed.protocol)?parsed.href:'#'}catch{return '#'}};
const external=(url,label)=>`<a href="${esc(safeUrl(url))}" target="_blank" rel="noopener noreferrer">${esc(label)}</a>`;
function pageHead(title,sub,eyebrow='RESEARCH, PEOPLE & PLACEMENT'){return `<div class="page-top"><div><p class="eyebrow">${eyebrow}</p><h1>${title}<span class="title-dot">.</span></h1><p class="page-subtitle">${sub}</p></div><span class="outline-badge">核验于 ${esc(catalog.updated_at)}</span></div>`}
function notice(){return `<div class="notice"><strong>持续扩充的核验样本</strong><span>已收录 ${records.length} 人、${new Set(records.map(r=>r.school)).size} 所培养院校。目标范围：北美研究前 50、港五、新加坡三所。名单与首职仍有缺口，比例仅描述已收集记录。<a href="#coverage">查看覆盖情况</a></span></div>`}
function select(name,label,opts){return `<label class="filter-label">${label}<select name="${name}">${opts.map(([v,t])=>option(v,t,filters[name])).join('')}</select></label>`}
function filterPanel(){return `<section class="filter-panel" aria-label="筛选候选人与去向"><div class="filter-top"><div class="segmented" role="group" aria-label="研究领域">${[['all','全部领域'],['marketing','全部 Marketing'],['qm','Quant'],['cb','Consumer Behavior'],['marketing_unclassified','Mkt 方向待分'],['io','IO']].map(([v,t])=>`<button type="button" class="segment ${filters.track===v?'selected':''}" data-track="${v}" aria-pressed="${filters.track===v}">${t}</button>`).join('')}</div><label class="search"><span aria-hidden="true">⌕</span><input type="search" name="q" value="${esc(filters.q)}" aria-label="搜索姓名、学校、JMP或关键词" placeholder="搜索姓名、学校、JMP…"></label></div><form id="filters"><div class="filter-grid">${select('period','时间口径',[['cohorts',`近四年名录 · ${archiveLabel()} · 含待核验`],['history',`已知首职年 · ${archiveLabel()}`],...catalog.archive_years.map(y=>[String(y),`${y} · placement 年`]),['current',`${cycleLabel()} · 当季求职`],['unresolved','去向 / 首职年待核验'],['all','全部记录 · 含待核验']])}${select('scope','院校范围',[['all','全部档案 · 含 IO'],['target','目标 58 校 · Marketing'],['extension','范围外扩展档案']])}${select('origin','博士培养地区',[['all','全部四个地区'],...['US','CA','HK','SG'].map(r=>[r,region(r)])])}${select('school','博士培养院校',[['all','全部院校'],...[...new Set([...records.map(r=>r.school),...catalog.programs.filter(p=>p.target_scope).map(p=>p.school)])].sort().map(x=>[x,x])])}${select('background','背景对照口径',Object.entries(BG))}</div><details class="advanced-filters"><summary>主题、方法与岗位筛选</summary><div class="filter-grid">${select('destination','去向地区',[['all','全球去向'],...tally(records,r=>r.destination_region).map(([r])=>[r,region(r)])])}${select('job','首次岗位类型',[['all','全部岗位'],...Object.entries(JOBS)])}${select('topic','研究主题',[['all','全部主题'],...tally(records,r=>r.topics).map(([t])=>[t,t])])}${select('method','研究方法',[['all','全部方法'],...tally(records,r=>r.methods).map(([m])=>[m,m])])}</div></details><div class="filter-bottom"><span id="filter-count" role="status" aria-live="polite"></span><button type="button" class="text-button" id="reset">重置筛选</button></div></form></section>`}
function stats(rs){const s=summarize(rs);return `<div class="stats-grid"><article class="stat-card"><p>筛选内研究者</p><strong>${fmt(s.count)}</strong><span>${s.schools} 所博士培养院校 · 人员去重</span></article><article class="stat-card"><p>已核验初始雇主</p><strong>${fmt(s.known)}</strong><span>${s.unknown} 条历史记录去向待核验</span></article><article class="stat-card"><p>教职去向</p><strong>${fmt(s.faculty)}<small> / ${s.known}</small></strong><span>占已知历史去向 ${percent(s.facultyShare)} · 含不同轨道</span></article><article class="stat-card dark"><p>当季求职者</p><strong>${fmt(s.onMarket)}</strong><span>筛选内仍在求职者</span></article></div>`}
function panel(title,sub,body,extra=''){return `<section class="panel ${extra}"><div class="panel-heading"><div><p class="eyebrow">${sub}</p><h2>${title}</h2></div></div>${body}</section>`}
function empty(text='没有符合条件的记录'){return `<div class="empty-state"><span>∅</span><h3>${text}</h3><p>可调整筛选，或到“覆盖与来源”查看资料缺口。未知信息不代表不存在。</p><button class="button secondary" data-reset>清除筛选</button></div>`}
function barList(entries,{colors=false,clickable=false}={}){const max=Math.max(1,...entries.map(e=>e[1]));return `<div class="bar-list">${entries.length?entries.slice(0,8).map(([key,n])=>`<div class="bar-row"><div class="bar-label">${clickable?`<button class="text-button" data-destination="${esc(key)}">${esc(region(key))}</button>`:esc(key)}</div><div class="bar-track"><span style="width:${n/max*100}%;background:${colors?JOB_COLORS[key]||'var(--green)':'var(--green)'}"></span></div><span class="bar-number">${n}</span></div>`).join(''):'<p class="muted">当前筛选没有可汇总的已核验记录。</p>'}</div>`}
function annualChart(rs){const hist=rs.filter(r=>r.status==='placed'&&r.market_cycle!==catalog.current_cycle);const years=/^20\d{2}$/.test(filters.period)?[Number(filters.period)]:catalog.history_years,max=Math.max(1,...years.map(y=>hist.filter(r=>r.placement_year===y).length));const used=Object.keys(JOBS).filter(j=>hist.some(r=>r.job_kind===j));return `<div class="annual-chart">${years.map(y=>{const rows=hist.filter(r=>r.placement_year===y);return `<div class="annual-row"><span class="year">${y}</span><div class="annual-track">${rows.length?`<div class="stack" style="width:${rows.length/max*100}%">${used.map(j=>{const n=rows.filter(r=>r.job_kind===j).length;return n?`<button title="${y} · ${JOBS[j]}：${n}人" aria-label="查看${y}年${JOBS[j]}${n}人" data-year="${y}" data-job="${j}" style="flex:${n};background:${JOB_COLORS[j]}">${n}</button>`:''}).join('')}</div>`:'<span class="no-year-data">暂无核验样本</span>'}</div><strong>${rows.length}</strong></div>`}).join('')}<div class="legend">${used.map(j=>`<span><i style="background:${JOB_COLORS[j]}"></i>${JOBS[j]}</span>`).join('')}</div></div><p class="chart-note">按明确的初始 placement / 入职年份计数。各年收集进度不同，柱高不代表市场规模变化；点击色块可查看明细。</p>`}
function comparisonCard(rs){const baseline=filterRecords(records,{...filters,background:'all'}),sub=baseline.filter(r=>filterRecords([r],{background:comparison}).length);const a=summarize(baseline),b=summarize(sub);return panel('相同筛选下，比较背景','COHORT COMPARISON',`<div class="compare-control"><label for="compare-bg">对照组定义</label><select id="compare-bg">${Object.entries(BG).filter(([k])=>k!=='all').map(([k,v])=>option(k,v,comparison)).join('')}</select></div><div class="compare-grid">${[[a,'整体已收集样本'],[b,BG[comparison]]].map(([s,t])=>`<div class="compare-card"><p>${t}</p><strong>${s.count}<small> 人</small></strong><dl><div><dt>已知历史去向</dt><dd>${s.known}</dd></div><div><dt>其中教职</dt><dd>${s.faculty} / ${s.known} <span>${percent(s.facultyShare)}</span></dd></div><div><dt>博士后</dt><dd>${s.postdoc}</dd></div><div><dt>当季求职</dt><dd>${s.onMarket}</dd></div></dl></div>`).join('')}</div><p class="chart-note">对照组是整体样本的子集，并非独立样本。继承上方时间、领域等条件，但用这里的背景定义替代上方背景筛选。教育地区不代表国籍或族裔。<br>${comparison.startsWith('cn_')?'尚无公开身份依据者保留未知，不归为“非中国人／非华裔”。':'本科资料不全可能造成选择偏差。'} 小样本不作显著性或因果判断。</p>`)}
function overview(rs){return `<div class="chart-grid">${panel('初始 placement 年度分布','FOUR-YEAR ARCHIVE',annualChart(rs))}${panel('全球去向','DESTINATION REGIONS',barList(tally(rs.filter(r=>r.status==='placed'&&r.destination),r=>r.destination_region||'UNKNOWN'),{clickable:true})+'<p class="chart-note">按首份岗位的工作地区计数；地区缺少明确依据时保留未核验。</p>')}</div><div class="chart-grid equal">${panel('研究主题分布','RESEARCH THEMES',barList(tally(rs,r=>r.topics))+'<p class="chart-note">根据已公开的研究领域和论文内容标注；一人可有多个主题，人数不可直接相加。</p>')}${comparisonCard(rs)}</div>${panel('追溯到具体研究者','RECENT RECORDS',table(rs.slice(0,6))+`<div class="panel-footer"><a href="#directory">查看筛选后的全部名录（${rs.length} 人）</a></div>`)}`}
function trackTags(r){const tags=r.tracks.filter(t=>t!=='marketing'||!r.tracks.some(x=>['qm','cb'].includes(x)));return tags.map(t=>`<span class="tag ${t}">${({marketing:'Marketing · 方向待分',qm:'Quant Mkt',cb:'Consumer Behavior',io:'IO'})[t]}</span>`).join('')}
function table(rs){if(!rs.length)return empty();return `<div class="table-scroll"><table class="records-table"><thead><tr><th>研究者 / 培养项目</th><th>研究与论文</th><th>首次去向 / 当前状态</th><th>时间与资料</th></tr></thead><tbody>${rs.map(r=>`<tr><td><button type="button" class="person-button" data-person="${esc(r.id)}">${esc(r.name)}</button><span class="cell-note">${esc(r.school)}</span><span class="cell-note">${esc(r.program)} · ${region(r.origin)}</span></td><td>${trackTags(r)}<p class="research-title">${esc(r.jmp||r.fields.slice(0,3).join(' · ')||'研究资料待补充')}</p>${r.methods.length?`<span class="cell-note">${esc(r.methods.slice(0,2).join(' · '))}</span>`:''}</td><td>${r.destination?`<strong class="destination-name">${esc(r.destination)}</strong><span class="cell-note">${esc(r.role||'职位名称未核验')} · ${region(r.destination_region)}</span>`:`<span class="status-badge">${r.status==='on_market'?'当季求职中':r.source_reported_placement?'首职待厘清':'去向待核验'}</span>${r.source_reported_placement?`<span class="cell-note">来源所报：${esc(r.source_reported_placement)}<br>尚非首职确认</span>`:''}`}<span class="cell-note">${JOBS[r.job_kind]||'待分类'}</span>${r.subsequent?.length?'<span class="tag">另有任职经历</span>':''}</td><td><strong>${r.status==='on_market'?esc(r.market_cycle?.replace('-','–')||'求职季待核验'):r.placement_year||'年份待核验'}</strong><span class="cell-note">${r.status==='on_market'?'求职季':'placement 年'}</span>${r.source_cohort_year?`<span class="cell-note">来源名单：${esc(r.source_cohort_label||r.source_cohort_year)}</span>`:''}${r.graduation_year?`<span class="cell-note">毕业：${r.graduation_year}</span>`:''}<button class="text-button source-button" data-person="${esc(r.id)}">${r.sources.length} 个来源</button></td></tr>`).join('')}</tbody></table></div>`}
function directory(rs){return `<section class="panel"><div class="panel-heading"><div><p class="eyebrow">TRACEABLE RECORDS</p><h2>${view==='current'?`${cycleLabel()} 候选人`:'Placement 名录'} <span class="count-pill">${rs.length}</span></h2></div><button class="button secondary" id="export-csv">导出当前筛选 CSV</button></div>${table(rs)}</section>`}
function renderResults(){let rs=filterRecords(records,filters);rs.sort((a,b)=>(b.placement_year||b.source_cohort_year||b.graduation_year||0)-(a.placement_year||a.source_cohort_year||a.graduation_year||0)||a.name.localeCompare(b.name));$('#filter-count').textContent=`匹配 ${rs.length} 人 · ${new Set(rs.map(r=>r.school)).size} 所培养院校`;$('#summary').innerHTML=stats(rs);$('#results').innerHTML=view==='overview'?overview(rs):directory(rs);wireResultActions(rs)}
function wireResultActions(rs){document.querySelectorAll('[data-person]').forEach(b=>b.onclick=()=>openPerson(b.dataset.person));document.querySelectorAll('[data-reset]').forEach(b=>b.onclick=reset);document.querySelectorAll('[data-year]').forEach(b=>b.onclick=()=>{filters.period=b.dataset.year;filters.job=b.dataset.job;location.hash='directory';if(view==='directory')mount()});document.querySelectorAll('[data-destination]').forEach(b=>b.onclick=()=>{filters.destination=b.dataset.destination;location.hash='directory';if(view==='directory')mount()});if($('#compare-bg'))$('#compare-bg').onchange=e=>{comparison=e.target.value;renderResults()};if($('#export-csv'))$('#export-csv').onclick=()=>exportCsv(rs)}
function reset(){filters={period:view==='current'?'current':'cohorts',scope:'all',track:'all',origin:'all',school:'all',job:'all',destination:'all',topic:'all',method:'all',background:'all',q:''};mount()}
function field(label,value){return `<div><dt>${label}</dt><dd>${esc(value||'未核验')}</dd></div>`}
function openPerson(id){const r=records.find(r=>r.id===id);if(!r)return;let dialog=$('#person-dialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='person-dialog';dialog.setAttribute('aria-labelledby','person-title');document.body.append(dialog);dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()})}dialog.innerHTML=`<div class="dialog-inner"><div class="dialog-top"><p class="eyebrow">RESEARCHER RECORD</p><button class="close-button" aria-label="关闭详情">×</button></div><h2 id="person-title">${esc(r.name)}</h2><p class="muted">${esc(r.school)} · ${esc(r.program)}</p>${trackTags(r)}<h3>研究</h3><dl class="detail-grid">${field('Job Market Paper',r.jmp)}${field('公开研究领域',r.fields.join(' · '))}${field('方法',r.methods.join(' · '))}${r.methods_raw?.length?field('方法原文',r.methods_raw.join(' · ')):''}${field('分类依据',r.field_evidence)}</dl><h3>时间与去向</h3><dl class="detail-grid">${field('求职季',r.market_cycle)}${field('首次 placement 年',r.placement_year)}${r.source_cohort_year?field('来源名单年份',r.source_cohort_label||r.source_cohort_year):''}${r.graduation_year?field('博士毕业年',r.graduation_year):''}${field('初始雇主',r.destination)}${r.source_reported_placement?field('来源表所报去向 · 首职待厘清',r.source_reported_placement):''}${field('初始岗位',r.role)}${field('任职地区',region(r.destination_region))}${field('岗位类别',JOBS[r.job_kind])}</dl>${r.subsequent?.length?`<h3>其他任职经历 · 不替代首职</h3><ul class="event-list">${r.subsequent.map(s=>`<li><strong>${esc(s.institution||s.employer||s.destination||'')}</strong><span>${esc(s.title||s.role||'')} ${esc(s.start_date||s.start_year||s.year||'')}${s.end_year?'–'+esc(s.end_year):''}</span></li>`).join('')}</ul>`:''}<h3>背景资料</h3><dl class="detail-grid">${field('本科院校',r.undergraduate?.institution)}${field('本科院校地区',region(r.undergraduate?.region))}${field('中国公民身份',r.identity?.chinese_national?.value==='yes'?'公开明确确认':'无公开核验依据')}${field('华裔身份',r.identity?.chinese_heritage?.value==='yes'?'本人公开自述':'无公开核验依据')}</dl><p class="chart-note">教育背景、国籍和族裔是独立字段；姓名不用于身份判断。</p>${r.notes?`<h3>核验备注</h3><p class="detail-note">${esc(r.notes)}</p>`:''}<h3>公开来源</h3><ul class="source-list">${r.sources.map(s=>`<li>${external(s.url,s.label||'原始资料')}<span>${esc(new URL(safeUrl(s.url),'https://example.com').hostname)}</span></li>`).join('')}</ul><p class="muted">最后核验：${esc(r.checked_at)}</p></div>`;dialog.querySelector('.close-button').onclick=()=>dialog.close();dialog.showModal()}
function exportCsv(rs){const header=['姓名','博士院校','项目','培养地区','研究领域','研究主题','研究方法','求职季','首次placement年','来源名单年份','博士毕业年','初始雇主','来源表所报去向（首职待厘清）','记录状态','核验备注','岗位','岗位类型','去向地区','JMP','本科院校','本科地区','中国公民公开确认','华裔公开自述','来源','核验日期'];const rows=rs.map(r=>[r.name,r.school,r.program,region(r.origin),r.fields.join('; '),r.topics.join('; '),r.methods.join('; '),r.market_cycle,r.placement_year,r.source_cohort_year,r.graduation_year,r.destination,r.source_reported_placement,r.status,r.notes,r.role,JOBS[r.job_kind],region(r.destination_region),r.jmp,r.undergraduate?.institution,region(r.undergraduate?.region),r.identity?.chinese_national?.value||'unknown',r.identity?.chinese_heritage?.value||'unknown',r.sources.map(s=>s.url).join(' | '),r.checked_at]);const blob=new Blob(['\uFEFF'+[header,...rows].map(row=>row.map(csvCell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`market-observatory-${catalog.updated_at}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),5000)}
function coverage(){return pageHead('先看覆盖，再读趋势','按培养项目与来源名单年份，记录名单核对进度和仍待补齐的资料。','COVERAGE & PROVENANCE')+notice()+coverageMarkup(catalog,records)}
function method(){return pageHead('让每个比较都有依据','这是一份持续建设的公开信息档案。以下规则与所有筛选、图表和导出数据保持一致。','METHOD & DEFINITIONS')+`<div class="method-grid">${panel('01 · 研究与地区范围','SCOPE',`<div class="prose"><p>收录美国、加拿大、香港和新加坡培养的 Marketing 全方向（含 Quant、Consumer Behavior、其他及待分类方向）及 Economics / Industrial Organization 博士毕业生与求职者，记录其全球去向。不限国籍。</p><p>本轮重点为北美 Marketing 研究前 50、香港 5 所、新加坡 3 所。采用 UTD 四本 Marketing 期刊的 2021–2025 年北美研究产出排序，固定清单版本。排名衡量研究产出，不代表就业质量，也不保证有 Marketing 博士；资格与资料缺口见覆盖页。Economics IO 作为扩展档案保留，未宣称完成 IO 全市场普查。</p><p>按明确自述、院系领域标签与论文证据识别研究方向。Marketing 细分方向与 IO 可以交叉，人数合计按人员去重。Marketing 项目人员不会因为缺少细分方向而被排除；研究方向与博士培养项目独立记录。进入 Marketing 系、在咨询公司工作，不直接作为领域证据。</p></div>`)}${panel('02 · 求职季和 placement 年','TIME',`<div class="prose"><p>${cycleLabel()} 是进行中的求职季。历史结果按明确的首次 placement 或就业开始年份归档，默认展示 ${archiveLabel()}；毕业年份不自动转换为求职季。</p><p>未知求职季保留为空。默认“近四年名录”保留来源表、毕业年或首职年落在近四年的非当季人员，包含首职未知者；按其中任一日期入选不能解读为同一毕业届。可切换“已知首职年”查看严格首职年份样本。“去向 / 首职年待核验”或“全部记录”也可查看缺失与冲突记录；没有明确首职年份的人员不进入年度图表。新一年添加到档案，历史记录不被删除。</p></div>`)}${panel('03 · 初始岗位和后续任职','OUTCOMES',`<div class="prose"><p>博士毕业转衔中的首份已确认职业岗位是首职统计依据（开始日期可能早于学位授予）。在读研究助理、实习与首职需要区分；经历性质或先后尚未厘清时，保留未知。先博士后再 Assistant Professor 的经历分别保留；同时公布的后续安排不改写第一段经历。</p><p>Assistant Professor 不自动标为 tenure-track；没有明确依据时显示“教职 · 轨道未核验”。失去信息不等于没有就业。</p></div>`)}${panel('04 · 身份与教育背景','BACKGROUND',`<div class="prose"><p>中国公民身份仅记录本人或可信公开资料的明确表述；华裔身份仅记录本人公开自述。每项需要独立来源，不依据姓名、照片、语言或学校推断。</p><p>“本科在中国大陆／香港／台湾”只描述教育地区，不代表国籍或族裔。身份或教育资料缺失时保留未知，不归入否定类别。</p></div>`)}${panel('05 · 计数、分母与小样本','INTERPRETATION',`<div class="prose"><p>教职占比 = 已知初始去向中的教职人数 ÷ 已知初始去向人数。分母包括博士后、企业等已知去向；当季求职者和去向未知者不进入该分母。</p><p>院校、年份和背景资料的收集程度不同。这里展示样本构成，不能估算整个市场的就业率、国籍差异或个人求职成功概率。小样本仅列人数，不做显著性检验。</p></div>`)}${panel('06 · 来源与更正','PROVENANCE',`<div class="prose"><p>优先核验院校历史 placement 名录，再与个人主页、CV 和接收单位资料交叉检查；参考聚合站用于发现线索。</p><p>研究主题是基于公开内容的整理标签，方法只在证据明确时记录。原始研究字段和全部来源保留在个人详情中。修订保留日期与说明。</p><p>本版：${esc(catalog.version)} · ${esc(catalog.updated_at)}。${esc(catalog.change_note||'')}</p></div>`)}</div>`}
function mount(){const titles={overview:['看见研究的下一站','以研究主题、方法与初始去向，观察 Marketing 全方向和 IO 就业市场。'],directory:['从论文，到 placement','筛选研究者、研究主题和全球去向。点开姓名可查看履历与核验来源。'],current:[`${cycleLabel()}，市场进行中`,'已明确参加本季求职的研究者。名单与结果正在陆续发布；空白去向不代表没有 offer。']};document.querySelectorAll('.nav-item').forEach(a=>{const on=a.hash==='#'+view;a.classList.toggle('active',on);if(on)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});if(view==='coverage'){main.innerHTML=coverage();bindCoverage(catalog,records,openPerson);return}if(view==='method'){main.innerHTML=method();return}const [title,sub]=titles[view];main.innerHTML=pageHead(title,sub)+notice()+'<div id="summary"></div>'+filterPanel()+'<div id="results"></div><p class="footer-note">每条记录可追溯 · 个人研究用途 · 姓名不用于身份推断 · 最新核验 '+esc(catalog.updated_at)+'</p>';$('#filters').onsubmit=e=>e.preventDefault();$('#filters').onchange=e=>{filters[e.target.name]=e.target.value;if(view==='current'&&e.target.name==='period'&&e.target.value!=='current'){location.hash='directory'}else renderResults()};$('.search input').oninput=e=>{filters.q=e.target.value;renderResults()};document.querySelectorAll('[data-track]').forEach(b=>b.onclick=()=>{filters.track=b.dataset.track;document.querySelectorAll('[data-track]').forEach(el=>{el.classList.toggle('selected',el===b);el.setAttribute('aria-pressed',String(el===b))});renderResults()});$('#reset').onclick=reset;renderResults()}
function route(){const next=location.hash.slice(1)||'overview';const previous=view;view=['overview','directory','current','coverage','method'].includes(next)?next:'overview';if(view==='current'){filters.period='current';filters.job='all'}else if(previous==='current'&&filters.period==='current')filters.period='cohorts';mount()}
try{const responses=await Promise.all([fetch('data/records.json',{cache:'no-cache'}),fetch('data/catalog.json',{cache:'no-cache'})]);if(responses.some(r=>!r.ok))throw new Error('data unavailable');[records,catalog]=await Promise.all(responses.map(r=>r.json()));configure({currentCycle:catalog.current_cycle,historyYears:catalog.history_years});document.querySelector('.nav-item[href="#current"]').innerHTML=`${cycleLabel()} 当季 <span>03</span>`;document.querySelector('.sidebar-foot').innerHTML=`历史档案 + 当季追踪<br><span>核验于 ${esc(catalog.updated_at)}</span>`;route();window.addEventListener('hashchange',route);registerTool()}catch(e){main.innerHTML=pageHead('资料暂未加载','请刷新页面重试；当前不会展示过期或占位的统计数字。')+`<button class="button" id="retry">重新加载</button>`;$('#retry').onclick=()=>location.reload();console.error('Market data load failed',e)}
function registerTool(){if(!document.modelContext?.registerTool)return;const controller=new AbortController();try{Promise.resolve(document.modelContext.registerTool({name:'filter_market_records',title:'筛选市场观察记录',description:'Apply the visible search and research-track filters; show matching records and return their names and first placements. Public evidence sample, not a census.',inputSchema:{type:'object',properties:{query:{type:'string'},track:{type:'string',enum:['all','marketing','qm','cb','marketing_unclassified','io']},period:{type:'string',enum:['cohorts','history','current','unresolved','all',...catalog.archive_years.map(String)]}},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){if(!input||typeof input!=='object'||Object.keys(input).some(k=>!['query','track','period'].includes(k))||input.query!==undefined&&typeof input.query!=='string'||input.track!==undefined&&!['all','marketing','qm','cb','marketing_unclassified','io'].includes(input.track)||input.period!==undefined&&!['cohorts','history','current','unresolved','all',...catalog.archive_years.map(String)].includes(input.period))throw new Error('Invalid market filter');filters={...filters,q:input.query??filters.q,track:input.track??filters.track,period:input.period??filters.period};view='directory';history.replaceState(null,'','#directory');mount();const rs=filterRecords(records,filters);return {count:rs.length,coverage:'partial evidence sample',records:rs.map(r=>({name:r.name,school:r.school,placement:r.destination,year:r.placement_year,cycle:r.market_cycle}))}}},{signal:controller.signal})).catch(()=>{});window.addEventListener('pagehide',()=>controller.abort(),{once:true})}catch{}}
